import type { ResourceGroup } from "@notation/resource";

export type VaultSecretOptions = {
  /** Keys the secret in state. The name in the store is generated by the vault's provider. */
  id: string;
  /**
   * A credential of another resource, such as `source.credentials.value` for
   * a source, or `token.credentials.Value` for an API token. Deploy writes
   * it to the store, and state holds a marker in its place.
   */
  value: string;
};

/** A secret that a vault declares. The router or the deployer binds it. */
export type VaultSecret = ResourceGroup;

/** The hub's write-only secret store. `secret()` declares a secret that the vault owns. */
export interface Vault<S extends VaultSecret = VaultSecret>
  extends ResourceGroup {
  readonly provider: string;
  secret(opts: VaultSecretOptions): S;
}
